create extension if not exists "pgcrypto";
create type public.user_role as enum ('buyer','seller','admin');
create type public.part_condition as enum ('new','reconditioned','used');
create type public.listing_status as enum ('draft','active','reserved','sold','archived');
create table public.profiles(id uuid primary key references auth.users on delete cascade,role public.user_role not null default 'buyer',display_name text not null,phone text,created_at timestamptz not null default now());
create table public.sellers(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id),business_name text not null,slug text not null unique,postcode text,verified_at timestamptz,rating numeric(2,1) check(rating between 0 and 5),created_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),parent_id uuid references public.categories(id),name text not null,slug text not null unique);
create table public.vehicles(id uuid primary key default gen_random_uuid(),make text not null,model text not null,generation text,year_from smallint,year_to smallint,engine text,engine_code text,gearbox_family text,gearbox_code text);
create table public.parts(id uuid primary key default gen_random_uuid(),seller_id uuid not null references public.sellers(id),category_id uuid references public.categories(id),title text not null,slug text not null unique,description text not null,manufacturer text,part_number text,oem_number text,gearbox_family text,gearbox_code text,condition public.part_condition not null,price_pence integer not null check(price_pence>=0),stock integer not null default 1 check(stock>=0),status public.listing_status not null default 'draft',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.part_images(id uuid primary key default gen_random_uuid(),part_id uuid not null references public.parts(id) on delete cascade,storage_path text not null,alt_text text not null,position smallint not null default 0);
create table public.part_fitments(part_id uuid not null references public.parts(id) on delete cascade,vehicle_id uuid not null references public.vehicles(id) on delete cascade,notes text,primary key(part_id,vehicle_id));
create table public.saved_parts(profile_id uuid not null references public.profiles(id) on delete cascade,part_id uuid not null references public.parts(id) on delete cascade,created_at timestamptz not null default now(),primary key(profile_id,part_id));
create table public.orders(id uuid primary key default gen_random_uuid(),buyer_id uuid not null references public.profiles(id),status text not null default 'pending',total_pence integer not null,created_at timestamptz not null default now());
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,part_id uuid not null references public.parts(id),seller_id uuid not null references public.sellers(id),quantity integer not null check(quantity>0),unit_price_pence integer not null);
create index parts_search_idx on public.parts using gin(to_tsvector('english',coalesce(title,'')||' '||coalesce(description,'')||' '||coalesce(oem_number,'')||' '||coalesce(gearbox_code,'')));
alter table public.profiles enable row level security; alter table public.sellers enable row level security; alter table public.parts enable row level security; alter table public.saved_parts enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security;
create policy "active parts are public" on public.parts for select using(status='active');
create policy "users manage own saved parts" on public.saved_parts for all using(profile_id=auth.uid()) with check(profile_id=auth.uid());
